using System.Security.Claims;
using MediFlow.Api.Data;
using MediFlow.Api.Models;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
namespace MediFlow.Api.Controllers;
[ApiController,Authorize,Route("api")]
public class RecordsController(AppDbContext db):ControllerBase{
 private int ClinicId=>int.Parse(User.FindFirstValue("clinicId")!);
 [HttpGet("dashboard")]public async Task<IActionResult> Dashboard()=>Ok(new{patients=await db.Patients.CountAsync(x=>x.ClinicId==ClinicId),doctors=await db.Doctors.CountAsync(x=>x.ClinicId==ClinicId),appointments=await db.Appointments.CountAsync(x=>x.ClinicId==ClinicId),upcoming=await db.Appointments.CountAsync(x=>x.ClinicId==ClinicId&&x.StartsAt>=DateTime.UtcNow&&x.Status=="Scheduled")});
 [HttpGet("patients")]public async Task<IActionResult> Patients()=>Ok(await db.Patients.Where(x=>x.ClinicId==ClinicId).OrderBy(x=>x.FullName).ToListAsync());
 [HttpPost("patients")][Authorize(Roles="Admin,Receptionist")]public async Task<IActionResult> AddPatient(Patient p){p.Id=0;p.ClinicId=ClinicId;if(!ModelState.IsValid)return ValidationProblem(ModelState);db.Patients.Add(p);await db.SaveChangesAsync();return Ok(p);}
 [HttpPut("patients/{id:int}")][Authorize(Roles="Admin,Receptionist")]public async Task<IActionResult> EditPatient(int id,Patient p){var old=await db.Patients.SingleOrDefaultAsync(x=>x.Id==id&&x.ClinicId==ClinicId);if(old==null)return NotFound();old.FullName=p.FullName;old.Phone=p.Phone;old.Email=p.Email;old.DateOfBirth=p.DateOfBirth;await db.SaveChangesAsync();return Ok(old);}
 [HttpDelete("patients/{id:int}")][Authorize(Roles="Admin")]public async Task<IActionResult> DeletePatient(int id){var p=await db.Patients.SingleOrDefaultAsync(x=>x.Id==id&&x.ClinicId==ClinicId);if(p==null)return NotFound();if(await db.Appointments.AnyAsync(x=>x.ClinicId==ClinicId&&x.PatientId==id))return Conflict("Patient has appointments");db.Patients.Remove(p);await db.SaveChangesAsync();return NoContent();}
 [HttpGet("doctors")]public async Task<IActionResult> Doctors()=>Ok(await db.Doctors.Where(x=>x.ClinicId==ClinicId).OrderBy(x=>x.FullName).ToListAsync());
 [HttpPost("doctors")][Authorize(Roles="Admin")]public async Task<IActionResult> AddDoctor(Doctor d){d.Id=0;d.ClinicId=ClinicId;if(!ModelState.IsValid)return ValidationProblem(ModelState);db.Doctors.Add(d);await db.SaveChangesAsync();return Ok(d);}
 [HttpPut("doctors/{id:int}")][Authorize(Roles="Admin")]public async Task<IActionResult> EditDoctor(int id,Doctor d){var old=await db.Doctors.SingleOrDefaultAsync(x=>x.Id==id&&x.ClinicId==ClinicId);if(old==null)return NotFound();old.FullName=d.FullName;old.Specialty=d.Specialty;old.Email=d.Email;await db.SaveChangesAsync();return Ok(old);}
 [HttpDelete("doctors/{id:int}")][Authorize(Roles="Admin")]public async Task<IActionResult> DeleteDoctor(int id){var d=await db.Doctors.SingleOrDefaultAsync(x=>x.Id==id&&x.ClinicId==ClinicId);if(d==null)return NotFound();if(await db.Appointments.AnyAsync(x=>x.ClinicId==ClinicId&&x.DoctorId==id))return Conflict("Doctor has appointments");db.Doctors.Remove(d);await db.SaveChangesAsync();return NoContent();}
 [HttpGet("appointments")]public async Task<IActionResult> Appointments()=>Ok(await db.Appointments.Where(x=>x.ClinicId==ClinicId).OrderBy(x=>x.StartsAt).Select(x=>new{x.Id,x.PatientId,patient=x.Patient!.FullName,x.DoctorId,doctor=x.Doctor!.FullName,x.StartsAt,x.Status,x.Notes}).ToListAsync());
 [HttpPost("appointments")][Authorize(Roles="Admin,Receptionist")]public async Task<IActionResult> AddAppointment(AppointmentInput a){if(!await db.Patients.AnyAsync(x=>x.Id==a.PatientId&&x.ClinicId==ClinicId)||!await db.Doctors.AnyAsync(x=>x.Id==a.DoctorId&&x.ClinicId==ClinicId))return BadRequest("Patient or doctor not in your clinic");if(!ValidStatus(a.Status))return BadRequest("Invalid status");var x=new Appointment{ClinicId=ClinicId,PatientId=a.PatientId,DoctorId=a.DoctorId,StartsAt=a.StartsAt,Status=a.Status,Notes=a.Notes};db.Appointments.Add(x);await db.SaveChangesAsync();return Ok(new{x.Id});}
 [HttpPut("appointments/{id:int}")][Authorize(Roles="Admin,Receptionist,Doctor")]public async Task<IActionResult> EditAppointment(int id,AppointmentInput a){var x=await db.Appointments.SingleOrDefaultAsync(x=>x.Id==id&&x.ClinicId==ClinicId);if(x==null)return NotFound();if(!await db.Patients.AnyAsync(p=>p.Id==a.PatientId&&p.ClinicId==ClinicId)||!await db.Doctors.AnyAsync(d=>d.Id==a.DoctorId&&d.ClinicId==ClinicId))return BadRequest("Invalid clinic references");if(!ValidStatus(a.Status))return BadRequest("Invalid status");x.PatientId=a.PatientId;x.DoctorId=a.DoctorId;x.StartsAt=a.StartsAt;x.Status=a.Status;x.Notes=a.Notes;await db.SaveChangesAsync();return Ok(new{x.Id});}
 [HttpDelete("appointments/{id:int}")][Authorize(Roles="Admin,Receptionist")]public async Task<IActionResult> DeleteAppointment(int id){var x=await db.Appointments.SingleOrDefaultAsync(x=>x.Id==id&&x.ClinicId==ClinicId);if(x==null)return NotFound();db.Appointments.Remove(x);await db.SaveChangesAsync();return NoContent();}
 private static bool ValidStatus(string s)=>s is "Scheduled" or "Completed" or "Cancelled";
}
